from fastapi import HTTPException
from typing import Optional, Dict, Any


class ShopFlowException(HTTPException):
    """ShopFlow 自定义异常基类"""

    def __init__(
        self, 
        status_code: int = 500, 
        detail: str = "Internal Server Error",
        headers: Optional[Dict[str, str]] = None
    ):
        super().__init__(status_code=status_code, detail=detail, headers=headers)


class OrderNotFoundException(ShopFlowException):
    """订单未找到异常"""

    def __init__(self, order_id: str):
        super().__init__(
            status_code=404,
            detail=f"Order {order_id} not found"
        )


class InvalidStatusTransitionException(ShopFlowException):
    """无效状态转换异常"""

    def __init__(self, current_status: str, new_status: str):
        super().__init__(
            status_code=422,
            detail=f"Cannot transition from {current_status} to {new_status}"
        )


class InvalidStatusValueException(ShopFlowException):
    """无效状态值异常"""

    def __init__(self, status_value: str):
        super().__init__(
            status_code=422,
            detail=f"Invalid status value: {status_value}"
        )


class InventoryNotFoundException(ShopFlowException):
    """库存未找到异常"""

    def __init__(self, product_id: str):
        super().__init__(
            status_code=404,
            detail=f"Inventory for product {product_id} not found"
        )


class InsufficientInventoryException(ShopFlowException):
    """库存不足异常"""

    def __init__(self, product_id: str, required: int, available: int):
        super().__init__(
            status_code=400,
            detail=f"Insufficient inventory for product {product_id}. Required: {required}, Available: {available}"
        )

