from pydantic import BaseModel, Field, validator
from typing import Optional
from datetime import datetime


class InventoryCreate(BaseModel):
    """创建库存请求体"""
    product_id: str = Field(..., min_length=1, description="产品 ID")
    quantity: int = Field(..., ge=0, description="库存数量")
    reserved: int = Field(default=0, ge=0, description="预留数量")

    @validator('product_id')
    def product_id_not_empty(cls, v: str) -> str:
        if not v.strip():
            raise ValueError('product_id cannot be empty')
        return v.strip()

    @validator('reserved')
    def reserved_not_exceed_quantity(cls, v: int, values: dict) -> int:
        if 'quantity' in values and v > values['quantity']:
            raise ValueError('reserved cannot exceed quantity')
        return v


class InventoryResponse(BaseModel):
    """库存响应体"""
    id: str
    product_id: str
    quantity: int
    reserved: int
    available_quantity: int
    created_at: datetime
    updated_at: Optional[datetime] = None

    class Config:
        from_attributes = True


class InventoryUpdate(BaseModel):
    """更新库存请求体"""
    quantity: Optional[int] = Field(None, ge=0, description="库存数量")
    reserved: Optional[int] = Field(None, ge=0, description="预留数量")

