from pydantic import BaseModel, Field, validator
from typing import List, Optional, Dict, Any
from datetime import datetime
from backend.models.enums import OrderStatus


class OrderItem(BaseModel):
    """订单项 schema"""
    product_id: str = Field(..., min_length=1, description="产品 ID")
    quantity: int = Field(..., gt=0, description="数量")
    price: float = Field(..., ge=0, description="单价")

    @validator('product_id')
    def product_id_not_empty(cls, v: str) -> str:
        if not v.strip():
            raise ValueError('product_id cannot be empty')
        return v.strip()


class OrderCreate(BaseModel):
    """创建订单请求体"""
    user_id: str = Field(..., min_length=1, description="用户 ID")
    total_amount: float = Field(..., ge=0, description="订单总金额")
    items: List[OrderItem] = Field(default_factory=list, description="订单项列表")

    @validator('user_id')
    def user_id_not_empty(cls, v: str) -> str:
        if not v.strip():
            raise ValueError('user_id cannot be empty')
        return v.strip()


class OrderResponse(BaseModel):
    """订单响应体"""
    id: str
    user_id: str
    status: str
    total_amount: float
    items: List[Dict[str, Any]]
    created_at: datetime
    updated_at: Optional[datetime] = None

    class Config:
        from_attributes = True


class OrderUpdateStatus(BaseModel):
    """更新订单状态请求体"""
    new_status: str = Field(..., description="新状态")

    @validator('new_status')
    def validate_status(cls, v: str) -> str:
        if not OrderStatus.is_valid(v):
            raise ValueError(f'Invalid status: {v}. Valid values: {[s.value for s in OrderStatus]}')
        return v
